def get_bundled_academy_dataset() -> dict[str, Any]:
    """Returns a fresh deep copy of the combined Academy Excel workbooks dataset."""
    return copy.deepcopy(BUNDLED_DATASET)


def ensure_academy_workbooks_loaded(store: Any, *, force: bool = False) -> dict[str, Any]:
    """Idempotently merges the bundled Excel workbooks (`قواعد شهر 9.xlsx` + `Academy_Management_Dashboard_2026-11-11.xlsx`)
    into `store` without deleting any existing user records.
    """
    data = get_bundled_academy_dataset()
    state = store.export_state()

    existing_codes = {str(s.get("code") or "").strip() for s in state.get("students", []) if s.get("code")}
    existing_ids = {str(s.get("id") or "").strip() for s in state.get("students", []) if s.get("id")}

    has_all_dash = all(f"STU-{i:03d}" in existing_codes for i in range(1, 64))
    has_all_sep = all(f"SEP-{i:03d}" in existing_codes for i in range(1, 48))
    if has_all_dash and has_all_sep and not force:
        return {
            "loaded": False,
            "reason": "already_loaded",
            "studentsCount": len(state.get("students", [])),
            "teachersCount": len(state.get("teachers", [])),
        }

    # Merge teachers & teacherMeta
    cur_teachers = list(state.get("teachers") or [])
    cur_meta = dict(state.get("teacherMeta") or {})
    teachers_added = 0
    for t in data["teachers"]:
        if t not in cur_teachers:
            cur_teachers.append(t)
            teachers_added += 1
        if t not in cur_meta or force:
            cur_meta[t] = copy.deepcopy(data["teacherMeta"].get(t, {"pct": 70, "defaultPct": 70}))

    # Merge students
    cur_students = list(state.get("students") or [])
    by_code = {str(s.get("code") or "").strip(): s for s in cur_students if s.get("code")}
    by_id = {str(s.get("id") or "").strip(): s for s in cur_students if s.get("id")}
    students_added = 0
    students_updated = 0

    for b_stu in data["students"]:
        b_code = str(b_stu.get("code") or "").strip()
        b_id = str(b_stu.get("id") or "").strip()
        target = by_code.get(b_code) or by_id.get(b_id)
        if target is None:
            cur_students.append(copy.deepcopy(b_stu))
            by_code[b_code] = cur_students[-1]
            by_id[b_id] = cur_students[-1]
            students_added += 1
        else:
            t_months = target.setdefault("months", {})
            changed = False
            for mk, m_val in (b_stu.get("months") or {}).items():
                if mk not in t_months or force:
                    t_months[mk] = copy.deepcopy(m_val)
                    changed = True
            if b_stu.get("schedule") and not target.get("schedule"):
                target["schedule"] = b_stu["schedule"]
                changed = True
            if b_code.startswith("SEP-") and target.get("adminStatus") != "منتهي الاشتراك":
                target["adminStatus"] = "منتهي الاشتراك"
                changed = True
            if changed:
                students_updated += 1

    # Map bundled student IDs to actual student IDs in state (in case a student already existed with another ID)
    id_remap = {}
    for b_stu in data["students"]:
        b_code = str(b_stu.get("code") or "").strip()
        b_id = str(b_stu.get("id") or "").strip()
        actual = by_code.get(b_code) or by_id.get(b_id)
        if actual:
            id_remap[b_id] = actual["id"]

    # Merge installments (avoiding duplicate receiptNo or (studentId, month))
    cur_inst = list(state.get("installments") or [])
    existing_rcp = {str(i.get("receiptNo") or "") for i in cur_inst}
    existing_stu_month_inst = {(str(i.get("studentId") or ""), str(i.get("month") or "")) for i in cur_inst}
    inst_added = 0
    for b_inst in data["installments"]:
        real_sid = id_remap.get(b_inst["studentId"], b_inst["studentId"])
        rcp = b_inst["receiptNo"]
        sm_key = (real_sid, b_inst["month"])
        if rcp not in existing_rcp and sm_key not in existing_stu_month_inst:
            inst_copy = copy.deepcopy(b_inst)
            inst_copy["studentId"] = real_sid
            cur_inst.append(inst_copy)
            existing_rcp.add(rcp)
            existing_stu_month_inst.add(sm_key)
            inst_added += 1

    # Merge payouts
    cur_payouts = list(state.get("payouts") or [])
    existing_payout_ids = {str(p.get("id") or "") for p in cur_payouts}
    existing_payout_tm = {(str(p.get("teacher") or ""), str(p.get("month") or "")) for p in cur_payouts}
    payouts_added = 0
    for b_pay in data["payouts"]:
        if b_pay["id"] not in existing_payout_ids and (b_pay["teacher"], b_pay["month"]) not in existing_payout_tm:
            cur_payouts.append(copy.deepcopy(b_pay))
            existing_payout_ids.add(b_pay["id"])
            existing_payout_tm.add((b_pay["teacher"], b_pay["month"]))
            payouts_added += 1

    # Merge study groups
    cur_groups = list(state.get("groups") or [])
    existing_group_ids = {str(g.get("id") or "") for g in cur_groups}
    groups_added = 0
    for b_grp in data["groups"]:
        if b_grp["id"] not in existing_group_ids:
            cur_groups.append(copy.deepcopy(b_grp))
            existing_group_ids.add(b_grp["id"])
            groups_added += 1

    state["teachers"] = cur_teachers
    state["teacherMeta"] = cur_meta
    state["students"] = cur_students
    state["installments"] = cur_inst
    state["payouts"] = cur_payouts
    state["groups"] = cur_groups
    state["onboarded"] = True

    store.replace_all(state, actor="academy_data_loader")
    return {
        "loaded": True,
        "teachersAdded": teachers_added,
        "studentsAdded": students_added,
        "studentsUpdated": students_updated,
        "installmentsAdded": inst_added,
        "payoutsAdded": payouts_added,
        "groupsAdded": groups_added,
        "studentsCount": len(cur_students),
        "teachersCount": len(cur_teachers),
    }


if __name__ == "__main__":
    from alahd_erp.config import resolve_app_home
    from alahd_erp.infrastructure.database import Store as _Store

    home = resolve_app_home()
    db_path = home / "alahd_erp_v1.sqlite3"
    s = _Store(db_path)
    try:
        res = ensure_academy_workbooks_loaded(s)
        print(json.dumps(res, ensure_ascii=False))
    finally:
        s.close()
